package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strings"
)

const mod = 998244353

type Matrix struct {
	n   int
	val [][2]int64
}

func NewMatrix(n int) *Matrix {
	m := &Matrix{n: n}
	m.val = make([][2]int64, n)
	for i := range m.val {
		m.val[i][0] = 0
		m.val[i][1] = 0
	}
	return m
}

func (m *Matrix) Mul(other *Matrix) *Matrix {
	n := m.n
	res := NewMatrix(n)
	for i := 0; i < n; i++ {
		for j := 0; j < n; j++ {
			sum := int64(0)
			for k := 0; k < n; k++ {
				sum = (sum + m.val[i][k]*other.val[k][j]) % mod
			}
			res.val[i][j] = sum
		}
	}
	return res
}

func (m *Matrix) Pow(exp int64) *Matrix {
	n := m.n
	// Identity matrix
	res := NewMatrix(n)
	for i := 0; i < n; i++ {
		res.val[i][i] = 1
	}
	base := m
	for exp > 0 {
		if exp&1 == 1 {
			res = res.Mul(base)
		}
		base = base.Mul(base)
		exp >>= 1
	}
	return res
