package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strings"
)

const mod = 998244353

type Matrix struct {
	n    int
	data [][]int64
}

func NewMatrix(n int) *Matrix {
	m := &Matrix{n: n}
	m.data = make([][]int64, n)
	for i := range m.data {
		m.data[i] = make([]int64, n)
	}
	return m
}

func (m *Matrix) Mul(other *Matrix) *Matrix {
	n := m.n
	result := NewMatrix(n)
	for i := 0; i < n; i++ {
		for k := 0; k < n; k++ {
			if m.data[i][k] == 0 {
				continue
			}
			mik := m.data[i][k]
			for j := 0; j < n; j++ {
				result.data[i][j] = (result.data[i][j] + mik*other.data[k][j]) % mod
			}
		}
	}
	return result
}

func (m *Matrix) Pow(exp int64) *Matrix {
	n := m.n
	result := NewMatrix(n)
	// identity
	for i := 0; i < n; i++ {
		result.data[i][i] = 1
	}
	base := m
	for exp > 0 {
		if exp%2 == 1 {
			result = result.Mul(base)
		}
		base = base.Mul(base)
		exp /= 2
	}
	return result
}

