const mod = 998244353

type Matrix struct {
	n   int
	val [][2]int64
}

func NewMatrix(n int) *Matrix {
	m := &Matrix{n: n}
	m.val = make([][2]int64, n)
	for i := 0; i < n; i++ {
		m.val[i][0] = 0
		m.val[i][1] = 0
	}
	return m
}

func (m *Matrix) Clone() *Matrix {
	nm := &Matrix{n: m.n}
	nm.val = make([][2]int64, m.n)
	for i := 0; i < m.n; i++ {
		nm.val[i][0] = m.val[i][0]
		nm.val[i][1] = m.val[i][1]
	}
	return nm
}

func (m *Matrix) Mul(other *Matrix) *Matrix {
	res := NewMatrix(m.n)
	for i := 0; i < m.n; i++ {
		for k := 0; k < m.n; k++ {
			if m.val[i][k] == 0 {
				continue
			}
			for j := 0; j < m.n; j++ {
				res.val[i][j] = (res.val[i][j] + m.val[i][k] * other.val[k][j]) % mod
			}
		}
	}
	return res
}

func (m *Matrix) Pow(exp int64) *Matrix {
	res := NewMatrix(m.n)
	// identity
	for i := 0; i < m.n; i++ {
		res.val[i][i] = 1
	}
	base := m.Clone()
	for exp > 0 {
		if exp&1 == 1 {
			res = res.Mul(base)
		}
		base = base.Mul(base)
		exp >>= 1
	}
	return res
}

