const MOD = 998244353

type Matrix struct {
	n    int
	data [][]int64
}

func NewMatrix(n int) *Matrix {
	m := &Matrix{n: n}
	m.data = make([][]int64, n)
	for i := range m.data {
		m.data[i] = make([]int64, n)
	}
	return m
}

func (m *Matrix) Mul(other *Matrix) *Matrix {
	res := NewMatrix(m.n)
	for i := 0; i < m.n; i++ {
		for k := 0; k < m.n; k++ {
			if m.data[i][k] == 0 {
