const mod = 998244353

type Matrix struct {
	size int
	data [][2]int
}

func NewMatrix(size int) *Matrix {
	m := &Matrix{size: size}
	m.data = make([][2]int, size)
	for i := range m.data {
		m.data[i][0] = 0
		m.data[i][1] = 0
	}
	return m
}

func (m *Matrix) Mul(other *Matrix) *Matrix {
	result := NewMatrix(m.size)
	for i := 0; i < m.size; i++ {
		for k := 0; k < m.size; k++ {
			if m.data[i][k] == 0 {
				continue
			}
			for j := 0; j < m.size; j++ {
				result.data[i][j] = (result.data[i][j] + m.data[i][k]*other.data[k][j]) % mod
			}
		}
	}
	return result
}

func (m *Matrix) Pow(exp int64) *Matrix {
	// Identity matrix
	result := NewMatrix(m.size)
	for i := 0; i < m.size; i++ {
		result.data[i][i] = 1
