const mod = 998244353

type Matrix struct {
	n    int
	data [][]int64
}

func NewMatrix(n int) *Matrix {
	data := make([][]int64, n)
	for i := range data {
		data[i] = make([]int64, n)
	}
	return &Matrix{n: n, data: data}
}

func (m *Matrix) Mul(other *Matrix) *Matrix {
	res := NewMatrix(m.n)
	for i := 0; i < m.n; i++ {
		for k := 0; k < m.n; k++ {
			if m.data[i][k] == 0 {
				continue
			}
			for j := 0; j < m.n; j++ {
				res.data[i][j] = (res.data[i][j] + m.data[i][k]*other.data[k][j]) % mod
			}
		}
	}
	return res
}

